 // Sidecar format: migration never writes project.json or moves its images.
 // The editor sees registered resource identities, never native file paths.
 public sealed class MatureCanvasStore {
  public const string EngineName="tldraw",PinnedEngineVersion="2.4.6",ManifestName="mature-canvas.json",TrustedOrigin="https://nook-canvas.local";
  public const int MaximumSceneBytes=32*1024*1024,MaximumResourceBytes=32*1024*1024,PreviewDimension=2048;
  const int MaximumRecords=100000,MaximumPoints=1000000;
  static readonly Regex ProjectId=new Regex("^[a-f0-9]{32}$",RegexOptions.CultureInvariant);
  static readonly Regex ObjectId=new Regex("^[a-zA-Z0-9_-]{1,128}$",RegexOptions.CultureInvariant);
  static readonly Regex RecordId=new Regex("^(document|page|shape|asset|binding):[a-zA-Z0-9_-]{1,128}$",RegexOptions.CultureInvariant);
  static readonly Regex ResourceName=new Regex("^[a-f0-9]{32}\\.(png|jpg|jpeg|gif|webp|bmp|tif|tiff|ico|avif|heic|heif|psd|psb|dng|cr2|cr3|nef|arw|orf|rw2|raf)$",RegexOptions.CultureInvariant|RegexOptions.IgnoreCase);
  static readonly HashSet<string> ShapeTypes=Set("image text line arrow draw geo group frame note highlight");
  static readonly HashSet<string> Colors=Set("black grey light-violet violet blue light-blue yellow orange green light-green light-red red white");
  readonly string root;readonly FreeCanvasStore legacy;
  public string Root {get{return root;}}
  static HashSet<string> Set(string words){return new HashSet<string>(words.Split(' '),StringComparer.Ordinal);}
  static Dictionary<string,object> Map(params object[] values){var map=new Dictionary<string,object>(StringComparer.Ordinal);for(int i=0;i<values.Length;i+=2)map.Add((string)values[i],values[i+1]);return map;}
  static JavaScriptSerializer Json(){return new JavaScriptSerializer{MaxJsonLength=MaximumSceneBytes*2,RecursionLimit=48};}
  public MatureCanvasStore(string dataRoot){legacy=new FreeCanvasStore(dataRoot);root=legacy.Root;Safe(root);}
  internal static bool IsId(string id){return id!=null&&ProjectId.IsMatch(id);}
  static bool Identity(string id){return id!=null&&ObjectId.IsMatch(id);}
  static void Safe(string path){for(string part=Path.GetFullPath(path);!string.IsNullOrEmpty(part);part=Path.GetDirectoryName(part))if((File.Exists(part)||Directory.Exists(part))&&(File.GetAttributes(part)&FileAttributes.ReparsePoint)!=0)throw new IOException("画布路径包含链接，不能安全读写。");}
  string Folder(string id){if(!IsId(id))throw new InvalidDataException("画布项目编号无效。");string path=Path.Combine(root,id);Safe(path);return path;}
  string Manifest(string id){string file=Path.Combine(Folder(id),ManifestName);Safe(file);return file;}
  static string Name(string value){value=(value??"").Trim();if(value.Length==0||value.Length>120)throw new InvalidDataException("项目名称需为 1 至 120 个字。");return value;}
  static string Hash(byte[] bytes){using(var hash=SHA256.Create())return BitConverter.ToString(hash.ComputeHash(bytes)).Replace("-","");}
  static byte[] ReadBounded(string file,int maximum){Safe(file);using(var input=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.Read)){if(input.Length<=0||input.Length>maximum)throw new InvalidDataException("画布文件为空或过大，原文件已保留。");var bytes=new byte[(int)input.Length];int offset=0,read;while(offset<bytes.Length&&(read=input.Read(bytes,offset,bytes.Length-offset))>0)offset+=read;if(offset!=bytes.Length||input.ReadByte()!=-1)throw new IOException("画布文件读取时发生变化。");return bytes;}}
  static void Atomic(string file,byte[] bytes,bool replace){Safe(file);Safe(file+".bak");string folder=Path.GetDirectoryName(file);Directory.CreateDirectory(folder);Safe(folder);string pending=Path.Combine(folder,"editor-write-"+Guid.NewGuid().ToString("N")+".tmp");try{using(var output=new FileStream(pending,FileMode.CreateNew,FileAccess.Write,FileShare.None)){output.Write(bytes,0,bytes.Length);output.Flush(true);}Safe(file);Safe(file+".bak");if(File.Exists(file)){if(!replace)throw new IOException("画布资源已存在，不能覆盖。");File.Replace(pending,file,file+".bak",true);}else File.Move(pending,file);}finally{if(File.Exists(pending))File.Delete(pending);}}
  public bool Exists(string id){return File.Exists(Manifest(id));}
  public static string ResourceUrl(string projectId,string fileId){if(!IsId(projectId)||!Identity(fileId))throw new InvalidDataException("图片资源编号无效。");return TrustedOrigin+"/resource/"+projectId+"/"+fileId;}
  public MatureCanvasDocument Create(string name){
   // New projects get an empty compatible legacy index. Mature saves never
   // change a pre-existing legacy manifest, including migrated annotations.
   var index=legacy.Create(Name(name));var document=Empty(index.Id,index.Name);Save(document);return document;
  }
  static MatureCanvasDocument Empty(string id,string name){var records=Map("document:document",Map("id","document:document","typeName","document","gridSize",10,"name",name,"meta",Map()),"page:page",Map("id","page:page","typeName","page","name","画布","index","a1","meta",Map()));return new MatureCanvasDocument{Version=1,Engine=EngineName,EngineVersion=PinnedEngineVersion,Id=id,Name=Name(name),Resources=new List<MatureCanvasResource>(),SceneJson=Json().Serialize(Map("document",Map("store",records,"schema",DefaultSchema()),"session",DefaultSession(1,0,0)))};}
  // Serialized by the actual 2.4.6 schema, not guessed from the latest SDK.
  static Dictionary<string,object> DefaultSchema(){return Map("schemaVersion",2,"sequences",Map("com.tldraw.store",4,"com.tldraw.asset",1,"com.tldraw.camera",1,"com.tldraw.document",2,"com.tldraw.instance",25,"com.tldraw.instance_page_state",5,"com.tldraw.page",1,"com.tldraw.instance_presence",5,"com.tldraw.pointer",1,"com.tldraw.shape",4,"com.tldraw.asset.bookmark",2,"com.tldraw.asset.image",5,"com.tldraw.asset.video",5,"com.tldraw.shape.group",0,"com.tldraw.shape.text",2,"com.tldraw.shape.bookmark",2,"com.tldraw.shape.draw",2,"com.tldraw.shape.geo",9,"com.tldraw.shape.note",7,"com.tldraw.shape.line",5,"com.tldraw.shape.frame",0,"com.tldraw.shape.arrow",5,"com.tldraw.shape.highlight",1,"com.tldraw.shape.embed",4,"com.tldraw.shape.image",4,"com.tldraw.shape.video",2,"com.tldraw.binding.arrow",0));}
  static Dictionary<string,object> DefaultSession(double zoom,double x,double y){return Map("version",0,"currentPageId","page:page","isFocusMode",false,"exportBackground",true,"isDebugMode",false,"isToolLocked",false,"isGridMode",false,"pageStates",new[]{Map("pageId","page:page","camera",Map("x",x,"y",y,"z",zoom),"selectedShapeIds",new string[0],"focusedGroupId",null)});}
  public MatureCanvasDocument Load(string id){string file=Manifest(id);if(!File.Exists(file))throw new FileNotFoundException("这个画布还没有新版记录，原画布已保留。",file);byte[] bytes=ReadBounded(file,MaximumSceneBytes*2);MatureCanvasDocument document;try{document=Json().Deserialize<MatureCanvasDocument>(new UTF8Encoding(false,true).GetString(bytes));}catch(Exception error){throw new InvalidDataException("新版画布记录损坏，原记录和备份不会被覆盖。",error);}Validate(document);if(document.Id!=id)throw new InvalidDataException("画布目录与记录编号不同。");ValidateResourceFiles(document);document.LoadedHash=Hash(bytes);return document;}
  public void Save(MatureCanvasDocument document){
   Validate(document);string file=Manifest(document.Id);ValidateResourceFiles(document);string lockName="Local\\NookMatureCanvas-"+Hash(Encoding.UTF8.GetBytes(file.ToUpperInvariant()));using(var mutex=new Mutex(false,lockName)){
    bool owns=false;try{try{owns=mutex.WaitOne(5000);}catch(AbandonedMutexException){owns=true;}if(!owns)throw new IOException("其他窗口正在保存画布，请稍后重试。");if(File.Exists(file)){if(document.LoadedHash==null||Hash(ReadBounded(file,MaximumSceneBytes*2))!=document.LoadedHash)throw new IOException("画布已被其他窗口修改或损坏，请另存项目；当前内容没有被覆盖。");}else if(document.LoadedHash!=null)throw new IOException("画布记录已移动，请另存项目。");
