     // Otherwise an index error would report failure after the scene was saved.
     string index=Path.Combine(Folder(document.Id),"project.json");Safe(index);if(!File.Exists(index))legacy.Save(new FreeCanvasDocument{Version=1,Id=document.Id,Name=document.Name,Zoom=1,Items=new List<FreeCanvasItem>()});
     document.Name=Name(document.Name);document.Updated=DateTime.UtcNow.ToString("o",CultureInfo.InvariantCulture);byte[] bytes=new UTF8Encoding(false).GetBytes(Json().Serialize(document));if(bytes.Length>MaximumSceneBytes*2)throw new InvalidDataException("画布记录过大，请拆分项目。");Atomic(file,bytes,true);document.LoadedHash=Hash(bytes);
    }finally{if(owns)mutex.ReleaseMutex();}
   }
  }
  public List<FreeCanvasProjectInfo> List(){
   Safe(root);var results=new List<FreeCanvasProjectInfo>();foreach(string folder in Directory.GetDirectories(root)){string id=Path.GetFileName(folder);if(!IsId(id))continue;var info=new FreeCanvasProjectInfo{Id=id};try{if(Exists(id)){var document=Load(id);info.Name=document.Name;info.Updated=document.Updated;info.Pinned=document.Pinned;info.Images=document.ImageCount;info.Text=document.TextCount;info.Drawing=document.ElementCount-document.ImageCount-document.TextCount;}else{var document=legacy.Load(id);info.Name=document.Name;info.Updated=document.Updated;info.Pinned=document.Pinned;info.Images=document.Items.Count(i=>i.Kind=="image");info.Text=document.Items.Count(i=>i.Kind=="text");info.Drawing=document.Items.Count(i=>i.IsDrawing);}}catch(Exception error){if(!(error is IOException)&&!(error is InvalidDataException)&&!(error is UnauthorizedAccessException)&&!(error is ArgumentException)&&!(error is InvalidOperationException))throw;info.Name="无法读取的项目 "+id.Substring(0,6);info.Updated="";info.Error=error.Message;}results.Add(info);}return results.OrderByDescending(p=>p.Updated,StringComparer.Ordinal).ThenBy(p=>p.Name,StringComparer.CurrentCulture).ToList();
  }
  public string ResourcePath(MatureCanvasDocument document,MatureCanvasResource resource){if(document==null||resource==null||!Identity(resource.FileId)||resource.Image==null||!ResourceName.IsMatch(resource.Image))throw new InvalidDataException("画布图片记录无效。");string path=Path.Combine(Folder(document.Id),resource.Legacy?"images":"editor-images",resource.Image);Safe(path);return path;}
  void ValidateResourceFiles(MatureCanvasDocument document){foreach(var resource in document.Resources){string file=ResourcePath(document,resource);if(!File.Exists(file))throw new FileNotFoundException("画布图片缺失，记录不会被覆盖。",file);var info=new FileInfo(file);if(info.Length<=0||info.Length>(resource.Legacy?256L*1024*1024:MaximumResourceBytes))throw new InvalidDataException("画布图片为空或过大。");}}
  public BitmapSource Preview(MatureCanvasDocument document,string fileId,int maxDimension=PreviewDimension){var resource=document.Resources.SingleOrDefault(r=>r.FileId==fileId);if(resource==null)throw new InvalidDataException("画布图片未注册。");string path=ResourcePath(document,resource);int width,height;return FreeCanvasStore.Decode(path,path,Math.Max(1,Math.Min(PreviewDimension,maxDimension)),CancellationToken.None,out width,out height);}
  static byte[] Png(BitmapSource image){int width,height;return Png(image,out width,out height);}
  static byte[] Png(BitmapSource image,out int width,out int height){if(image==null||image.PixelWidth<1||image.PixelHeight<1||(long)image.PixelWidth*image.PixelHeight>1000000000)throw new InvalidDataException("图片尺寸无效或过大。");BitmapSource bounded=image;if(Math.Max(image.PixelWidth,image.PixelHeight)>PreviewDimension){double ratio=(double)PreviewDimension/Math.Max(image.PixelWidth,image.PixelHeight);bounded=new TransformedBitmap(image,new ScaleTransform(ratio,ratio));bounded.Freeze();}width=bounded.PixelWidth;height=bounded.PixelHeight;var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bounded));using(var output=new MemoryStream()){encoder.Save(output);if(output.Length>MaximumResourceBytes)throw new InvalidDataException("画布图片过大。");return output.ToArray();}}
  public byte[] ReadFile(MatureCanvasDocument document,string fileId){return Png(Preview(document,fileId));}
  public MatureCanvasResource AddImage(MatureCanvasDocument document,BitmapSource image,string fileId=null){return RegisterBytes(document,fileId??Guid.NewGuid().ToString("N"),Png(image),"image/png",".png");}
  public MatureCanvasResource RegisterImage(MatureCanvasDocument document,string source,string fileId=null){int width,height;return RegisterImage(document,source,out width,out height,fileId);}
  // Return the encoded preview's size while it is already decoded. Importing
  // must not reopen and decode the saved PNG just to recover two dimensions.
  internal MatureCanvasResource RegisterImage(MatureCanvasDocument document,string source,out int previewWidth,out int previewHeight,string fileId=null){
   if(string.IsNullOrWhiteSpace(source)||!Path.IsPathRooted(source)||!(source.StartsWith("\\\\",StringComparison.Ordinal)||(source.Length>=3&&source[1]==':'&&source[2]=='\\'))||source.IndexOf("://",StringComparison.Ordinal)>=0||!FreeCanvasStore.SupportedImage(source))throw new NotSupportedException("请拖入本机绝对路径图片文件，文件夹不会展开。");source=Path.GetFullPath(source);Safe(source);if(!File.Exists(source))throw new FileNotFoundException("图片不存在。",source);long maximum=Path.GetExtension(source).Equals(".svg",StringComparison.OrdinalIgnoreCase)?8L*1024*1024:256L*1024*1024;if(new FileInfo(source).Length<=0||new FileInfo(source).Length>maximum)throw new InvalidDataException("图片为空或过大。");
