  }
  public MatureCanvasResource RegisterDataUrl(MatureCanvasDocument document,string fileId,string dataUrl,string mimeType){
   Validate(document);if(!Identity(fileId)||dataUrl==null||dataUrl.Length>MaximumResourceBytes*4/3+256)throw new InvalidDataException("图片编号或大小无效。");string extension=MimeExtension(mimeType);string prefix="data:"+mimeType+";base64,";if(!dataUrl.StartsWith(prefix,StringComparison.Ordinal))throw new InvalidDataException("画布只接受有明确格式的内嵌图片。");byte[] bytes;try{bytes=Convert.FromBase64String(dataUrl.Substring(prefix.Length));}catch(FormatException error){throw new InvalidDataException("图片编码无效。",error);}if(bytes.Length==0||bytes.Length>MaximumResourceBytes)throw new InvalidDataException("图片为空或过大。");
