  }
  static string MimeExtension(string mime){switch(mime){case "image/png":return ".png";case "image/jpeg":return ".jpg";case "image/gif":return ".gif";case "image/webp":return ".webp";case "image/bmp":return ".bmp";default:throw new InvalidDataException("画布只接受栅格图片，SVG 等设计文件需先生成安全预览。");}}
  MatureCanvasResource RegisterBytes(MatureCanvasDocument document,string fileId,byte[] bytes,string mime,string extension){
   Validate(document);if(!Identity(fileId))throw new InvalidDataException("图片编号无效。");var existing=document.Resources.SingleOrDefault(r=>r.FileId==fileId);if(existing!=null){string path=ResourcePath(document,existing);if(existing.MimeType!=mime||Hash(ReadBounded(path,existing.Legacy?256*1024*1024:MaximumResourceBytes))!=Hash(bytes))throw new IOException("同一图片编号已注册不同内容，现有图片不会被覆盖。");return existing;}
