  }
  public string BrowserScene(MatureCanvasDocument document){Validate(document);return document.SceneJson;}
  public MatureCanvasDocument CopyProject(MatureCanvasDocument source,string name){
   Validate(source);ValidateResourceFiles(source);var target=Empty(Guid.NewGuid().ToString("N"),Name(name));target.Pinned=source.Pinned;var scene=Scene(source.SceneJson);var records=Records(scene);foreach(var value in records.Values){var record=Object(value,"记录");if((string)record["typeName"]=="asset"){var props=Object(record["props"],"资源属性");props["src"]=ResourceUrl(target.Id,FileFromUrl(source.Id,(string)props["src"]));}else if((string)record["typeName"]=="document")record["name"]=target.Name;}target.SceneJson=Json().Serialize(scene);
