   // no recursive cleanup ever relies on user-controlled project metadata.
   var copiedPaths=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var resource in source.Resources){var copy=new MatureCanvasResource{FileId=resource.FileId,Image=resource.Image,MimeType=resource.MimeType,Legacy=resource.Legacy};string destination=ResourcePath(target,copy);if(copiedPaths.Add(destination))Atomic(destination,ReadBounded(ResourcePath(source,resource),copy.Legacy?256*1024*1024:MaximumResourceBytes),false);target.Resources.Add(copy);}
   string old=Path.Combine(Folder(source.Id),"project.json");if(File.Exists(old))Atomic(Path.Combine(Folder(target.Id),"legacy-recovery.json"),ReadBounded(old,128*1024*1024),false);string previous=Manifest(source.Id);if(File.Exists(previous))Atomic(Path.Combine(Folder(target.Id),"mature-canvas.source.json"),ReadBounded(previous,MaximumSceneBytes*2),false);if(File.Exists(previous+".bak"))Atomic(Path.Combine(Folder(target.Id),"mature-canvas.source.json.bak"),ReadBounded(previous+".bak",MaximumSceneBytes*2),false);Save(target);return target;
  }
  public MatureCanvasDocument CreateFromLegacy(FreeCanvasDocument source){
   FreeCanvasStore.Validate(source);if(Exists(source.Id))return Load(source.Id);var document=Empty(source.Id,source.Name);document.Pinned=source.Pinned;var scene=Scene(document.SceneJson);var records=Records(scene);int order=1;
   foreach(var item in source.Items){string shapeId="shape:"+item.Id;var meta=Map("nookLegacy",Map("kind",item.Kind,"color",item.Color??"auto","stroke",item.Stroke,"fontSize",item.FontSize,"width",item.Width,"height",item.Height));var shape=Map("id",shapeId,"typeName","shape","type",item.Kind=="image"?"image":item.Kind=="stroke"?"draw":item.Kind=="rectangle"||item.Kind=="ellipse"?"geo":item.Kind,"x",item.X,"y",item.Y,"rotation",0,"index",Index(order++),"parentId","page:page","isLocked",false,"opacity",1,"meta",meta);string color=PaletteColor(item.Color),size=StrokeSize(item.Stroke);Dictionary<string,object> props;
    if(item.Kind=="image"){string path=legacy.ImagePath(source.Id,item.Image);if(!File.Exists(path))throw new FileNotFoundException("旧画布图片缺失，迁移没有覆盖原记录。",path);document.Resources.Add(new MatureCanvasResource{FileId=item.Id,Image=item.Image,MimeType=LegacyMime(item.Image),Legacy=true});string assetId="asset:"+item.Id;records[assetId]=Map("id",assetId,"typeName","asset","type","image","props",Map("w",item.Width,"h",item.Height,"name",item.Image,"mimeType","image/png","src",ResourceUrl(source.Id,item.Id),"isAnimated",false),"meta",Map());props=Map("assetId",assetId,"w",item.Width,"h",item.Height,"playing",true,"url","","crop",null,"flipX",false,"flipY",false);}
    else if(item.Kind=="text"){double scale=item.FontSize/24;props=Map("color",color,"size","m","font","sans","text",item.Text,"textAlign","start","w",item.Width/scale,"autoSize",false,"scale",scale);}
    else if(item.Kind=="line"){props=Map("color",color,"dash","solid","size",size,"scale",StrokeScale(item.Kind,item.Stroke,size),"spline","line","points",Map("a1",Map("id","a1","index","a1","x",0,"y",0),"a2",Map("id","a2","index","a2","x",item.EndX-item.X,"y",item.EndY-item.Y)));}
    else if(item.Kind=="arrow"){props=Map("color",color,"labelColor",color,"fill","none","dash","solid","size",size,"scale",StrokeScale(item.Kind,item.Stroke,size),"bend",0,"start",Map("x",0,"y",0),"end",Map("x",item.EndX-item.X,"y",item.EndY-item.Y),"arrowheadStart","none","arrowheadEnd","arrow","text","","font","sans","labelPosition",.5);}
    else if(item.Kind=="stroke"){double minX=item.Points.Min(p=>p.X),minY=item.Points.Min(p=>p.Y);shape["x"]=minX;shape["y"]=minY;props=Map("color",color,"fill","none","dash","solid","size",size,"scale",StrokeScale(item.Kind,item.Stroke,size),"segments",new[]{Map("type","free","points",item.Points.Select(p=>Map("x",p.X-minX,"y",p.Y-minY,"z",.5)).ToArray())},"isComplete",true,"isClosed",false,"isPen",false);}
    else{shape["x"]=Math.Min(item.X,item.EndX);shape["y"]=Math.Min(item.Y,item.EndY);props=Map("geo",item.Kind=="ellipse"?"ellipse":"rectangle","color",color,"labelColor",color,"fill","none","dash","solid","size",size,"scale",StrokeScale(item.Kind,item.Stroke,size),"font","sans","w",Math.Max(1,Math.Abs(item.EndX-item.X)),"h",Math.Max(1,Math.Abs(item.EndY-item.Y)),"growY",0,"url","","text","","align","middle","verticalAlign","middle");}
