   }
   scene["session"]=DefaultSession(source.Zoom,source.PanX/source.Zoom,source.PanY/source.Zoom);document.SceneJson=Json().Serialize(scene);Save(document);return document;
  }
  static string LegacyMime(string image){switch(Path.GetExtension(image).ToLowerInvariant()){case ".jpg":case ".jpeg":return "image/jpeg";case ".gif":return "image/gif";case ".webp":return "image/webp";case ".bmp":return "image/bmp";default:return "image/png";}}
  static string StrokeSize(double stroke){return stroke<=2?"s":stroke<=4?"m":stroke<=7?"l":"xl";}
  // Verified pinned utilities apply scale to stroke width, not point geometry.
